/**
 * Generates a private DSA key using OpenSSL commands and returns it in PEM format.
 *
 * This function creates a temporary file for storing DSA parameters, generates the parameters,
 * then uses them to generate the private key. The temporary file is cleaned up after use.
 *
 * @return The generated DSA private key in PEM format as a string, or NULL on error.
 */
char* create_dsa_key() {
    // Create a unique temporary filename for the parameter file
    char param_filename[] = "/tmp/tempXXXXXX";
    int fd = mkstemp(param_filename);

    if (fd == -1) {
        return NULL;
    }

    close(fd);  // Close the descriptor as we don't need it open

    const char* key_length = "2048";  // Using a default key length of 2048 bits
    char* command_params = malloc(strlen("openssl dsaparam -out ") + strlen(param_filename) + strlen(" ") + strlen(key_length) + 1);

    if (!command_params) {
        unlink(param_filename);
        return NULL;
    }

    sprintf(command_params, "openssl dsaparam -out %s %s", param_filename, key_length);

    char* params_output = execute_command(command_params);

    free(command_params);

    if (params_output == NULL) {
        unlink(param_filename);
        return NULL;
    }

    free(params_output);  // We don't need the parameters output

    char* command_key = malloc(strlen("openssl gendsa ") + strlen(param_filename) + 1);

    if (!command_key) {
        unlink(param_filename);
        return NULL;
    }

    sprintf(command_key, "openssl gendsa %s", param_filename);

    char* key_output = execute_command(command_key);

    free(command_key);

    unlink(param_filename);  // Clean up the temporary file

    if (key_output == NULL) {
        return NULL;
    }

    return key_output;
}
